import {makeWordSearch,selectedCells,activityAnswer,orderedChoices,orderedIndices} from './missions.js';
const escape=(value='')=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,attrs='',className='')=>`<button type="button" data-action="activity-${action}" ${attrs} class="activity-card ${className}">${escape(text)}</button>`;
const audio=text=>`<button type="button" class="icon-btn small" data-action="speak" data-text="${escape(text)}" aria-label="Dengar: ${escape(text)}">🔊</button>`;
const controls=()=>`<div class="btn-row activity-controls">${button('undo','Undur')}${button('reset','Mula Semula')}${button('submit','Semak','','primary')}</div>`;
export function activityView(item,state,{done=false,two=false,guidance=false,enrichment=false}={}){
 const choices=orderedChoices(item,state);
 if(item.type==='choice')return `<div class="choice-list">${choices.map((word,k)=>`<div class="choice-row"><button class="answer" data-action="answer" data-answer="${escape(word)}"><span class="letter">${'ABCDEF'[k]}</span>${escape(word)}</button>${audio(word)}</div>`).join('')}</div>`;
 if(item.type==='match')return `<div class="match-board ${state.matchHint?'picture-hint':''}"><div><h3>A · Kata dasar</h3>${button('match-a',item.base,`aria-pressed="${state.matchSelected}"`,state.matchSelected?'selected':'')}${audio(item.base)}</div><div class="match-connector" aria-hidden="true">${state.selection?'━━━━':'┄┄┄┄'} →</div><div><h3>B · Kata berimbuhan</h3>${choices.map(word=>`<div class="card-and-audio">${button('match-b',word,`data-value="${escape(word)}" ${state.matchSelected?'':'disabled'} aria-pressed="${state.selection===word}"`,state.selection===word?'selected':'')}${audio(word)}</div>`).join('')}</div></div><p class="help">${state.selection?`${escape(item.base)} → ${escape(state.selection)}. Tekan Semak.`:'Pilih A dahulu, kemudian pilih B.'}</p>${controls()}`;
 if(item.type==='search'){
  const {grid}=makeWordSearch(item),selected=new Set(selectedCells(state.start,state.end).map(p=>p.y*8+p.x));
  return `<p class="search-target">Jejak kata: <strong>${escape(item.answer.toUpperCase())}</strong> ${audio(item.answer)}</p><div class="word-search" role="group" aria-label="Grid cari perkataan 8 baris dan 8 lajur">${grid.flatMap((row,y)=>row.map((letter,x)=>{const i=y*8+x;return button('cell',letter,`data-cell="${i}" aria-label="Baris ${y+1}, lajur ${x+1}, ${letter}" ${done?'disabled':''}`,`${selected.has(i)?'selected':''} ${state.start===i?'start-cell':''} ${state.hintStart===i?'hint-cell':''}`);})).join('')}</div><p class="help" aria-live="polite">${state.start==null?'Pilih huruf pertama.':state.end==null?'Sekarang pilih huruf terakhir.':`Pilihan: ${escape(activityAnswer(item,state).toUpperCase()||'Pilih satu baris atau lajur dari awal ke akhir.')}`}</p>${done?'':controls()}`;
 }
 if(item.type==='scramble')return `<div class="scramble-answer" aria-label="Perkataan yang disusun" aria-live="polite">${state.tokens.length?state.tokens.map(i=>`<span>${escape(item.pieces[i])}</span>`).join(''):'<span class="muted">Susun kepingan di sini</span>'}</div><div class="piece-bank">${orderedIndices(item.pieces,state,'pieceOrder').map(i=>{const piece=item.pieces[i];return `<div class="card-and-audio">${button('piece',piece,`data-index="${i}" ${state.tokens.includes(i)?'disabled':''}`)}${audio(piece)}</div>`;}).join('')}</div><p class="help">Kepingan ini membantu ejaan. Selepas disusun, baca perkataan penuh.</p>${controls()}`;
 if(item.type==='blank')return `<div class="blank-sentence"><span>Anggota polis</span> ${button('blank-slot',state.selection||'________',`aria-label="Pilih tempat kosong" aria-pressed="${!!state.blankSelected}"`,state.blankSelected?'selected':'')} <span>${escape(item.object)}</span></div>${enrichment?`<label class="check-row"><input id="activity-typing" type="checkbox" ${state.typing?'checked':''}> Taip perkataan sendiri</label>`:''}${state.typing?`<label for="activity-draft">Perkataan kamu</label><input id="activity-draft" maxlength="40" autocomplete="off" value="${escape(state.draft)}">`:`<div class="piece-bank">${choices.map(word=>`<div class="card-and-audio">${button('blank-word',word,`data-value="${escape(word)}" ${state.blankSelected?'':'disabled'}`,state.selection===word?'selected':'')}${audio(word)}</div>`).join('')}</div>`}${controls()}`;
 if(item.type==='sentence')return `<div class="sentence-demo"><span aria-hidden="true">▣ → ▢</span> Pilih kad, kemudian pilih ruang bernombor. Kamu juga boleh menyeret kad. ${audio(item.instruction)}</div><div class="sentence-slots" aria-label="Ruang bina ayat">${state.slots.map((card,index)=>button('slot',`${index+1}. ${card==null?'Letak kad di sini':item.cards[card]}`,`data-slot="${index}" ${card!=null?`data-drag-card="${card}" draggable="true"`:''}`,card!=null?'filled':'')).join('')}</div><div class="sentence-bank" aria-label="Bank kad perkataan">${orderedIndices(item.cards,state,'cardOrder').map(index=>{const card=item.cards[index];return `<div class="card-and-audio">${button('card',card,`data-index="${index}" data-drag-card="${index}" draggable="true" aria-pressed="${state.selectedCard===index}"`,`${state.selectedCard===index?'selected':''} ${state.slots.includes(index)?'placed':''}`)}${audio(card)}</div>`;}).join('')}</div><p class="help" aria-live="polite">${state.selectedCard==null?'Pilih satu kad.':'Kad dipilih. Pilih ruang untuk meletakkannya.'} Pilih kad yang sudah diletakkan untuk menukar susunan.</p>${controls()}`;
 return '';
}
